import { unstable_cache, revalidateTag } from 'next/cache';
import { after } from 'next/server';
import SyncButton from './sync-button';
import { getCatalogSnapshot, runCatalogSync } from '@/lib/db';

const currency = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD'
});

const formatTimestamp = value =>
  new Intl.DateTimeFormat('en-US', {
    dateStyle: 'medium',
    timeStyle: 'short'
  }).format(new Date(value));

const getCachedCatalog = unstable_cache(
  async () => getCatalogSnapshot(),
  ['catalog-snapshot'],
  { tags: ['products'] }
);

const availabilityTone = availability => {
  if (availability === 'In Stock') return 'good';
  if (availability === 'Low Stock') return 'warn';
  return 'bad';
};

export default async function Page() {
  const { items, lastSyncedAt, syncInFlight } = await getCachedCatalog();

  async function syncCatalogAction() {
    'use server';

    after(async () => {
      const result = await runCatalogSync();
      if (!result?.skipped) {
        revalidateTag('products');
      }
    });
  }

  return (
    <main className="page">
      <div className="page__wash" aria-hidden="true" />
      <section className="hero">
        <div className="hero__copy">
          <p className="eyebrow">Admin catalog</p>
          <h1>Product catalog control</h1>
          <p className="lead">
            Read-optimized browsing backed by cached catalog data. Trigger
            background syncs when ERP/PIM updates roll in.
          </p>
        </div>
        <form className="hero__form" action={syncCatalogAction}>
          <SyncButton />
          <p className="hint">
            Syncs run asynchronously. Continue working while catalog data
            refreshes in the background.
          </p>
        </form>
      </section>

      <section className="status-grid">
        <div className="status-card">
          <span className="status-label">Last synced</span>
          <span className="status-value">{formatTimestamp(lastSyncedAt)}</span>
        </div>
        <div className="status-card">
          <span className="status-label">Cache tag</span>
          <span className="status-value">products</span>
        </div>
        <div className="status-card">
          <span className="status-label">Sync state</span>
          <span className="status-value">
            {syncInFlight ? 'Syncing in background' : 'Idle / cached'}
          </span>
        </div>
      </section>

      <section className="table-card">
        <header className="table-card__header">
          <div>
            <h2>SKU overview</h2>
            <p className="subtle">
              {items.length} active products. Cached for fast, read-heavy admin
              use.
            </p>
          </div>
          <div className="pill-group">
            <span className="pill">Region: Global</span>
            <span className="pill">Channel: DTC + Retail</span>
            <span className="pill">Pricing: USD</span>
          </div>
        </header>
        <div className="table-scroll">
          <table>
            <thead>
              <tr>
                <th>SKU</th>
                <th>Product</th>
                <th>Category</th>
                <th>Status</th>
                <th>Availability</th>
                <th className="numeric">Inventory</th>
                <th className="numeric">Price</th>
              </tr>
            </thead>
            <tbody>
              {items.map((product, index) => (
                <tr
                  key={product.id}
                  style={{ '--row': index } as React.CSSProperties}
                >
                  <td className="mono">{product.id}</td>
                  <td>{product.name}</td>
                  <td>{product.category}</td>
                  <td>
                    <span className="badge badge--neutral">
                      {product.status}
                    </span>
                  </td>
                  <td>
                    <span
                      className={`badge badge--${availabilityTone(
                        product.availability
                      )}`}
                    >
                      {product.availability}
                    </span>
                  </td>
                  <td className="numeric mono">{product.inventory}</td>
                  <td className="numeric mono">{currency.format(product.price)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </main>
  );
}
